import { afterAll, beforeAll, describe, expect, it } from "vitest";
import request from "supertest";
import { like } from "drizzle-orm";
import {
  catsTable,
  db,
  observationsTable,
  photosTable,
  pool,
  sightingsTable,
} from "@workspace/db";
import app from "../app";

// SYC-43 part 2 plan, test P3-2, public half: the public GET /api/cats/:id is
// byte-for-byte what it was before PR 3. The snapshot file next to this test
// was written from `main` before any PR 3 code existed, and is never
// regenerated by PR 3. The team cat page (lib/teamCatView.ts) builds its own
// shape; if the public route were ever sent through it, or the team view's
// exact positions or history leaked into this payload, the bytes would change
// and this test would go red.
//
// Regenerated once, on purpose, by SYC-41 (data spine PR 6, #95): blurring
// changed this payload (cell centre, locationPrecision/locationCellM, dates
// not times, no sighting positions). Nothing else in it changed.
//
// Only the database's own serial ids are swapped for placeholders; every other
// byte, including key order, is compared as sent.

const PREFIX = "vitest-p32-";
const at = (iso: string) => new Date(iso);

let catId: number;
const sightingIds: number[] = [];
const photoIds: number[] = [];

// Observations are append-only (a database trigger), so they stay behind in
// the throwaway test database; everything else this file seeds is removed.
async function cleanup() {
  await db.delete(sightingsTable).where(like(sightingsTable.deviceId, `${PREFIX}%`));
  await db.delete(catsTable).where(like(catsTable.name, `${PREFIX}%`));
  await db.delete(photosTable).where(like(photosTable.publicId, `${PREFIX}%`));
}

beforeAll(async () => {
  await cleanup();
  const photos = await db
    .insert(photosTable)
    .values(
      ["main", "s1", "s2"].map((p) => ({
        publicId: `${PREFIX}${p}`,
        data: Buffer.from(`fake ${p}`).toString("base64"),
        mime: "image/jpeg",
        createdAt: at("2026-09-01T09:00:00Z"),
      })),
    )
    .returning({ id: photosTable.id });
  photoIds.push(...photos.map((p) => p.id));

  const [cat] = await db
    .insert(catsTable)
    .values({
      name: `${PREFIX}Μιμή`,
      description: "Sleeps on the church steps",
      primaryPhotoId: photoIds[0]!,
      lat: 37.4451234,
      lng: 24.9423456,
      discovererDeviceId: `${PREFIX}device-discoverer`,
      createdAt: at("2026-09-01T09:00:00Z"),
    })
    .returning({ id: catsTable.id });
  catId = cat!.id;

  const sightings = await db
    .insert(sightingsTable)
    .values([
      {
        catId,
        deviceId: `${PREFIX}device-a`,
        photoId: photoIds[1]!,
        lat: 37.4452345,
        lng: 24.9424567,
        status: "resolved",
        createdAt: at("2026-09-10T08:30:00Z"),
      },
      {
        catId,
        deviceId: `${PREFIX}device-b`,
        photoId: photoIds[2]!,
        lat: 37.4453456,
        lng: 24.9425678,
        status: "resolved",
        createdAt: at("2026-09-20T17:45:00Z"),
      },
    ])
    .returning({ id: sightingsTable.id });
  sightingIds.push(...sightings.map((s) => s.id));

  // A team statement and a spotter's clipped ear: the team page shows both,
  // with authors and the resolver's Likely; the public page must not.
  await db.insert(observationsTable).values([
    {
      catId,
      kind: "life_status",
      value: { status: "street", reason: "seen by the team" },
      accountId: "00000000-0000-4000-8000-0000000000a3",
      roleAtTime: "staff",
      observedAt: at("2026-09-15T10:00:00Z"),
      createdAt: at("2026-09-15T10:00:00Z"),
    },
    {
      catId,
      kind: "ear_tip",
      value: { clipped: true, side: "left" },
      deviceId: `${PREFIX}device-a`,
      roleAtTime: "public",
      sightingId: sightingIds[0]!,
      photoId: photoIds[1]!,
      observedAt: at("2026-09-10T08:30:00Z"),
      createdAt: at("2026-09-10T08:31:00Z"),
    },
  ]);
});

afterAll(async () => {
  await cleanup();
  await pool.end();
});

describe("P3-2 (public half): GET /api/cats/:id is unchanged by PR 3", () => {
  it("sends exactly the bytes it sent before PR 3", async () => {
    const res = await request(app).get(`/api/cats/${catId}`);
    expect(res.status).toBe(200);
    // Express sends JSON.stringify's output, so a parse and re-stringify is
    // the identity: checked first, so the swap below can't hide a byte.
    expect(JSON.stringify(JSON.parse(res.text))).toBe(res.text);
    const body = JSON.parse(res.text) as {
      cat: { id: unknown };
      sightings: { id: unknown; catId: unknown }[];
    };
    body.cat.id = "<cat>";
    for (const s of body.sightings) {
      s.id = `<sighting-${sightingIds.indexOf(s.id as number) + 1}>`;
      s.catId = s.catId === catId ? "<cat>" : s.catId;
    }
    const text = JSON.stringify(body);
    await expect(text).toMatchFileSnapshot(
      "./__snapshots__/cats.publicDetail.p3-2.txt",
    );
  });
});
